    let group = node.create_channel("Voice", vec![invitee.public()]).await.unwrap();
    crate::node::test_support::settle_group_metadata(&node, group);
    assert_eq!(node.group_voice_member(group, &node.user_id()).unwrap(), Some(node.account_id()));
    assert_eq!(node.group_voice_member(group, &invitee.public().user_id()).unwrap(), None);
    assert_eq!(node.group_voice_member(crate::eventlog::ConversationId::new([91; 32]), &node.user_id()).unwrap(), None);
}
